                           sms_reminders, sms_marketing_credits, active)
values ('soyonne', 'Chez Soyonne', 'beltab.app@gmail.com', 'beltab.app@gmail.com', '9 rue de Lancry, 75010 Paris', '09 60 51 60 42', 'https://soyonne.beltab.app',
        false, 0, true)
on conflict (client_slug) do nothing;

-- 3) Salle, tables et services (seulement si le restaurant n'en a encore aucun)
do $$
declare sp uuid;
begin
  if not exists (select 1 from restaurant_spaces where client_slug = 'soyonne') then
    insert into restaurant_spaces (client_slug, name, sort_order) values ('soyonne', 'Salle', 0) returning id into sp;
    insert into restaurant_tables (client_slug, space_id, name, seats) values
      ('soyonne', sp, 'T1', 2),
      ('soyonne', sp, 'T2', 2),
      ('soyonne', sp, 'T3', 2),
      ('soyonne', sp, 'T4', 4),
      ('soyonne', sp, 'T5', 4),
      ('soyonne', sp, 'T6', 6);
  end if;
  if not exists (select 1 from restaurant_services where client_slug = 'soyonne') then
    insert into restaurant_services (client_slug, name, start_time, end_time, sort_order) values
      ('soyonne', 'Midi', '11:30', '15:30', 0),
      ('soyonne', 'Soir', '18:30', '22:30', 1);
  end if;
end $$;

-- 4) Accès /admin pour les comptes de Will (l'équipe du resto : sql/acces-equipe.sql, à la signature)
insert into public.restaurant_admins (user_id, client_slug)
select u.id, s.slug
from auth.users u
cross join (values ('soyonne')) as s(slug)
where u.email in ('beltab.app@gmail.com', 'sowonboxx@gmail.com')
  and not exists (select 1 from public.restaurant_admins a where a.user_id = u.id and a.client_slug = s.slug);

-- Vérification : une ligne par élément, tout doit être à « oui »
select 'carte' as quoi, exists(select 1 from menu_data where client_slug = 'soyonne') as ok
union all select 'emails', exists(select 1 from resa_settings where client_slug = 'soyonne')
union all select 'tables', exists(select 1 from restaurant_tables where client_slug = 'soyonne')
union all select 'services', exists(select 1 from restaurant_services where client_slug = 'soyonne')
union all select 'accès Will', exists(select 1 from restaurant_admins where client_slug = 'soyonne');
